for sample in samples:
    raw = sample.raw_kind
    if raw != TYPE_UNSET:
        raw &= 0xf  # Strip upper nibble
        sample.raw_kind = raw

    if raw in (TYPE_NO_CHANGE, TYPE_IGNORE):
        # Inherit last valid type
        if last_valid != TYPE_UNSET:
            sample.raw_kind = last_valid
    else:
        last_valid = raw
